import{_ as a,c as t,o as i,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Mentorship","description":"","frontmatter":{"title":"Mentorship"},"headers":[],"relativePath":"privacy/mentorship.md","filePath":"privacy/mentorship.md","lastUpdated":null}'),o={name:"privacy/mentorship.md"};function n(s,e,h,l,p,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="mentorship" tabindex="-1">Mentorship <a class="header-anchor" href="#mentorship" aria-label="Permalink to &quot;Mentorship&quot;">​</a></h1><h2 id="mentorship-space" tabindex="-1">Mentorship Space <a class="header-anchor" href="#mentorship-space" aria-label="Permalink to &quot;Mentorship Space&quot;">​</a></h2><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><p>Update any of the details below. This was discussed in the admin chat <a href="https://matrix.to/#/!MBhgrJVelFkuOJNrsh:irregularchat.com/$J9LPTrQ8mkD7Gzkr6Kn0s1I7hx-WWSma8tfrtm75CmQ?via=irregularchat.com&amp;via=matrix.org" target="_blank" rel="noreferrer">here</a> and passed through the off-topic chat for any glaring gaps</p><p>Working notepad found <a href="https://cryptpad.irregularchat.com/pad/#/2/pad/edit/fBn5TxJJt0XQ1cWuY3A2hgdP/" target="_blank" rel="noreferrer">here on cryptpad</a> ### Problem Statement &gt; A critical challenge emerges in the Irregular Chat community: effectively scaling mentorship to meet the high demand for specialized guidance against a backdrop of limited mentor availability. Existing frameworks, spanning official military to community-based, show their age and lack the necessary flexibility to meet members’ diverse goals, from technical skill development to career advancement. This gap stifles individual growth potential and prevents the full application of collective expertise. Innovating an adaptive, scalable mentorship model becomes essential, aiming to forge meaningful connections between mentors and mentees tailored to specific needs and aspirations.</p><h3 id="just-cause" tabindex="-1">Just Cause <a class="header-anchor" href="#just-cause" aria-label="Permalink to &quot;Just Cause&quot;">​</a></h3><blockquote><p>to perpetually innovate mentorship within the Irregular Chat community, ensuring it remains adaptive and scalable to meet ever-evolving needs. We aim to foster an environment where every member can access personalized mentorship, unlocking individual potential and collective expertise.</p></blockquote><h3 id="community-spaces" tabindex="-1">Community Spaces <a class="header-anchor" href="#community-spaces" aria-label="Permalink to &quot;Community Spaces&quot;">​</a></h3><h3 id="matrix" tabindex="-1">Matrix <a class="header-anchor" href="#matrix" aria-label="Permalink to &quot;Matrix&quot;">​</a></h3><ul><li><p><a href="https://mentors.irregularchat.com" target="_blank" rel="noreferrer">Tools for Mentors</a> The members of this room are pressed for time as it is so the expectation is to keep discussions brief and valuable. This space is intended for the main mentors within the IrregularChat community.</p></li><li><p>&#39; This space is NOT intended to be the connecting point between mentor and mentee, guide people seeking this to <a href="https://mentorship.lobby.irregularchat.com" target="_blank" rel="noreferrer">Mentorship Lobby</a>.</p></li><li><p>&#39; This is NOT an Off Topic Chat.</p></li><li><p><a href="https://coaches.irregularchat.com" target="_blank" rel="noreferrer">Tools for Coaches and Guides</a></p></li><li><p><a href="https://mentorship.lobby.irregularchat.com" target="_blank" rel="noreferrer">Mentorship Lobby</a> ### Signal</p></li><li><p><a href="https://signal.group/#CjQKIK1ZgrwarftIWNMiE_6P9x0J7-yuHdpAChXy7wSMNWZHEhAf9WEpzfEX5-kWocepnugP" target="_blank" rel="noreferrer">Mentors Space</a> The members of this room are pressed for time as it is so the expectation is to keep discussions brief and valuable. This space is intended for the main mentors within the IrregularChat community.</p></li><li><p>This space is NOT intended to be the connecting point between mentor and mentee, guide people seeking this to <a href="https://mentorship.lobby.irregularchat.com" target="_blank" rel="noreferrer">Mentorship Lobby</a>.</p></li><li><p>This is NOT an Off Topic Chat.</p></li></ul><h3 id="resources-mentorship" tabindex="-1">Resources ### Mentorship <a class="header-anchor" href="#resources-mentorship" aria-label="Permalink to &quot;Resources ### Mentorship&quot;">​</a></h3><h3 id="coaching-guides" tabindex="-1">Coaching / Guides <a class="header-anchor" href="#coaching-guides" aria-label="Permalink to &quot;Coaching / Guides&quot;">​</a></h3><h3 id="sponsorship" tabindex="-1">Sponsorship <a class="header-anchor" href="#sponsorship" aria-label="Permalink to &quot;Sponsorship&quot;">​</a></h3><h3 id="other-communities-mentorship" tabindex="-1">Other Communities ### Mentorship <a class="header-anchor" href="#other-communities-mentorship" aria-label="Permalink to &quot;Other Communities ### Mentorship&quot;">​</a></h3><h3 id="coaching-guides-1" tabindex="-1">Coaching / Guides <a class="header-anchor" href="#coaching-guides-1" aria-label="Permalink to &quot;Coaching / Guides&quot;">​</a></h3><h3 id="sponsorship-1" tabindex="-1">Sponsorship <a class="header-anchor" href="#sponsorship-1" aria-label="Permalink to &quot;Sponsorship&quot;">​</a></h3>',16)])])}const u=a(o,[["render",n]]);export{d as __pageData,u as default};
